<script setup lang="ts">
import ReleaseNotesContent from './ReleaseNotesContent.vue'
import {dateTime,releaseNoteLines} from '../../utils/update-center'
const props=defineProps<{items:{version:string;installedAt?:string;releaseNotes:string;miniProgramUpdateRequired?:boolean}[];component:'framework'|'application';currentVersion?:string|null}>()
const expanded=ref<Record<string,boolean>>({})
const records=computed(()=>props.items.map((item,index)=>({...item,key:item.version+'|'+(item.installedAt||'')+'|'+index})).sort((a,b)=>(Date.parse(b.installedAt||'')-Date.parse(a.installedAt||''))||b.version.localeCompare(a.version,undefined,{numeric:true})).map(item=>({...item,canExpand:releaseNoteLines(item.releaseNotes).filter(line=>line.text.trim()).length>3})))
</script>
<template><ol class="divide-y divide-default" aria-label="版本更新日志"><li v-for="release in records" :key="release.key" class="py-4 first:pt-0"><div class="mb-3 flex flex-wrap items-center justify-between gap-2"><div class="flex items-center gap-2"><span class="text-sm font-semibold">v{{release.version}}</span><UBadge v-if="release.version===currentVersion" color="neutral" variant="subtle" size="sm">当前版本</UBadge></div><time v-if="release.installedAt" :datetime="release.installedAt" class="text-xs tabular-nums text-muted">{{dateTime(release.installedAt)}}</time><span v-else class="text-xs text-muted">时间未记录</span></div><ReleaseNotesContent :notes="release.releaseNotes" :component="component" :mini-program-update-required="release.miniProgramUpdateRequired" :limit="expanded[release.key]?undefined:3"/><UButton v-if="release.canExpand" variant="link" size="sm" class="mt-2 px-0" :aria-expanded="!!expanded[release.key]" @click="expanded[release.key]=!expanded[release.key]">{{expanded[release.key]?'收起日志':'展开全部日志'}}</UButton></li></ol></template>
